-- E-commerce schema + base data for an Indian D2C brand. All money in INR (₹).
-- Orders, new customers, reviews and stock are generated by grow.py.
-- Column comments are read by the agent (as an MCP resource), so keep them accurate.
DROP TABLE IF EXISTS reviews, inventory, festivals, orders, products, customers CASCADE;

CREATE TABLE customers (
  id serial PRIMARY KEY,
  name text NOT NULL,
  email text UNIQUE NOT NULL,
  phone text,
  city text NOT NULL,
  region text NOT NULL CHECK (region IN ('North', 'South', 'East', 'West')),
  pincode text,
  created_at date NOT NULL
);
COMMENT ON TABLE customers IS 'People who bought from us. One row per customer.';
COMMENT ON COLUMN customers.created_at IS 'Signup date';
COMMENT ON COLUMN customers.email IS 'Hidden for analysts';
COMMENT ON COLUMN customers.phone IS 'Hidden for analysts';
COMMENT ON COLUMN customers.pincode IS '6-digit Indian delivery pincode';

CREATE TABLE products (
  id serial PRIMARY KEY,
  name text NOT NULL,
  category text NOT NULL,
  price_inr numeric(12, 2) NOT NULL CHECK (price_inr > 0),
  cost_inr numeric(12, 2) NOT NULL CHECK (cost_inr >= 0)
);
COMMENT ON TABLE products IS 'Catalogue. Software and Services are digital: no courier, prepaid only.';
COMMENT ON COLUMN products.price_inr IS 'Selling price per unit';
COMMENT ON COLUMN products.cost_inr IS 'Our cost per unit (for margin = price - cost)';

CREATE TABLE orders (
  id serial PRIMARY KEY,
  customer_id int NOT NULL REFERENCES customers (id),
  product_id int NOT NULL REFERENCES products (id),
  quantity int NOT NULL CHECK (quantity > 0),
  amount_inr numeric(14, 2) NOT NULL,
  channel text NOT NULL CHECK (channel IN ('Website', 'Amazon', 'Flipkart', 'Meesho')),
  payment_method text NOT NULL CHECK (payment_method IN ('COD', 'Prepaid')),
  courier text,
  status text NOT NULL CHECK (status IN ('pending', 'completed', 'refunded', 'rto')),
  order_date date NOT NULL,
  delivered_date date
);
COMMENT ON TABLE orders IS 'One row per order line. Region comes from the customer (JOIN customers).';
COMMENT ON COLUMN orders.amount_inr IS 'Order value = quantity * price. Revenue counts only status = completed';
COMMENT ON COLUMN orders.channel IS 'Where it was sold: Website, Amazon, Flipkart, Meesho';
COMMENT ON COLUMN orders.payment_method IS 'COD (cash on delivery) or Prepaid';
COMMENT ON COLUMN orders.courier IS 'Delivery partner; NULL for digital products';
COMMENT ON COLUMN orders.status IS 'pending = not delivered yet; completed = delivered and kept; '
  'refunded = delivered then returned; rto = return to origin: undelivered, came back (no money)';
COMMENT ON COLUMN orders.delivered_date IS 'NULL unless delivered (completed / refunded)';

CREATE TABLE reviews (
  id serial PRIMARY KEY,
  order_id int NOT NULL REFERENCES orders (id),
  product_id int NOT NULL REFERENCES products (id),
  rating int NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment text NOT NULL,
  created_at date NOT NULL
);
COMMENT ON TABLE reviews IS 'Customer reviews after delivery (English and Hinglish)';

CREATE TABLE inventory (
  product_id int NOT NULL REFERENCES products (id),
  region text NOT NULL CHECK (region IN ('North', 'South', 'East', 'West')),
  on_hand int NOT NULL CHECK (on_hand >= 0),
  reorder_point int NOT NULL,
  lead_time_days int NOT NULL,
  updated_at date NOT NULL,
  PRIMARY KEY (product_id, region)
);
COMMENT ON TABLE inventory IS 'Current stock per product in each regional warehouse (physical products only)';
COMMENT ON COLUMN inventory.on_hand IS 'Units in stock now; 0 = out of stock';
COMMENT ON COLUMN inventory.reorder_point IS 'Reorder when on_hand falls below this';
COMMENT ON COLUMN inventory.lead_time_days IS 'Days for a restock to arrive from the supplier';

CREATE TABLE festivals (
  name text NOT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  boost numeric(3, 1) NOT NULL
);
COMMENT ON TABLE festivals IS 'Indian festivals and sale events; boost = expected sales multiplier';

